    const front = makeWheel(0.31, tireMat, goldMat)
    front.position.set(0, 0.31, -0.82)
    this.wheels.push(rearLeft, rearRight, front)
    this.model.add(...this.wheels)

    this.model.add(rod([-0.72, 0.35, 0.6], [0.72, 0.35, 0.6], 0.035, goldMat))

    // ---- chassis & seat --------------------------------------------------
    this.model.add(box(1.28, 0.09, 1.32, darkMat, 0, 0.53, 0.18))
    this.model.add(box(1.34, 0.12, 0.16, goldMat, 0, 0.58, 0.86))
    this.model.add(box(1.18, 0.14, 0.62, redMat, 0, 0.82, 0.42))
    this.model.add(box(1.18, 0.58, 0.12, redMat, 0, 1.13, 0.76))
    this.model.add(box(1.24, 0.05, 0.66, creamMat, 0, 0.9, 0.42))

    for (const x of [-0.62, 0.62]) {
      this.model.add(rod([x, 0.34, 0.2], [x, 0.62, 0.62], 0.03, goldMat))
    }
    for (const z of [-0.5, 0.55]) {
      this.model.add(rod([0, 0.55, z], [0, 0.85, z - 0.12], 0.03, goldMat))
    }

    // ---- canopy ----------------------------------------------------------
    const artMats = [
      greenMat,
      greenMat,
      goldMat,
      goldMat,
      new THREE.MeshStandardMaterial({ map: textures.rickshawArt, roughness: 0.48, metalness: 0.05 }),
      new THREE.MeshStandardMaterial({ color: 0x8f1026, roughness: 0.7 }),
    ]
    const artPanel = new THREE.Mesh(new THREE.BoxGeometry(1.6, 1.06, 0.07), artMats)
    artPanel.position.set(0, 1.55, 0.92)
    this.model.add(artPanel)

    for (const [x, z] of [[-0.78, 0.14], [0.78, 0.14], [-0.78, 0.9], [0.78, 0.9]]) {
      this.model.add(rod([x, 0.62, z], [x, 1.98, z], 0.028, goldMat))
    }

    const roof = box(1.7, 0.075, 1.04, greenMat, 0, 2.02, 0.52)
    this.model.add(roof)
    this.model.add(box(1.78, 0.035, 1.1, goldMat, 0, 2.07, 0.52))
    for (const side of [-1, 1]) {
      const flap = box(0.46, 0.06, 1.04, greenMat, side * 0.95, 1.96, 0.52)
      flap.rotation.z = side * -0.32
      this.model.add(flap)
      const trim = box(0.48, 0.03, 1.08, goldMat, side * 0.99, 1.93, 0.52)
      trim.rotation.z = side * -0.32
      this.model.add(trim)
      const sidePanel = box(0.045, 0.62, 0.94, greenMat, side * 0.84, 1.4, 0.5)
      this.model.add(sidePanel)
      this.model.add(box(0.05, 0.06, 0.98, goldMat, side * 0.85, 1.71, 0.5))
    }

    // fringe under the art panel
    for (let i = 0; i < 11; i++) {
      const tassel = new THREE.Mesh(new THREE.SphereGeometry(0.045, 6, 5), goldMat)
      tassel.position.set(-0.68 + i * 0.136, 0.99, 0.94)
      this.model.add(tassel)
    }

    // little Bangladesh flag
    const flagPole = rod([0.8, 2.06, 0.96], [0.8, 2.52, 0.96], 0.014, goldMat)
    this.model.add(flagPole)
    this.flag = new THREE.Mesh(
      new THREE.PlaneGeometry(0.3, 0.18),
      new THREE.MeshStandardMaterial({ map: textures.flag, side: THREE.DoubleSide, roughness: 0.8 }),
    )
    this.flag.position.set(0.8 - 0.152, 2.42, 0.96)
    this.flag.rotation.y = Math.PI / 2
    this.model.add(this.flag)

    // tail lamps
    for (const x of [-0.56, 0.56]) {
      const lamp = new THREE.Mesh(
        new THREE.SphereGeometry(0.07, 8, 8),
        new THREE.MeshStandardMaterial({ color: 0xff5a3c, emissive: 0xff2a10, emissiveIntensity: 2.2 }),
      )
      lamp.position.set(x, 1.09, 0.97)
      this.model.add(lamp)
      const halo = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: textures.glow,
          color: 0xff4a22,
          transparent: true,
          opacity: 0.7,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      )
      halo.scale.set(0.5, 0.5, 1)
      halo.position.set(x, 1.09, 0.99)
      this.model.add(halo)
    }

    // number plate
    const plate = new THREE.Mesh(
      new THREE.PlaneGeometry(0.42, 0.15),
      new THREE.MeshBasicMaterial({ map: textures.plate, transparent: true }),
    )
    plate.position.set(0, 0.66, 0.99)
    this.model.add(plate)

    // ---- driver ----------------------------------------------------------
    this.driver = new THREE.Group()
    this.driver.position.set(0, 0.9, -0.42)
    this.model.add(this.driver)

    const shirtTexture = textures.checkered.clone()
    shirtTexture.needsUpdate = true
    shirtTexture.repeat.set(2, 2)
    const shirtMat = new THREE.MeshStandardMaterial({ map: shirtTexture, roughness: 0.85 })

    const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.23, 0.54, 10), shirtMat)
    torso.position.set(0, 0.3, 0)
    torso.rotation.x = 0.22
    this.driver.add(torso)

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.155, 14, 12), skinMat)
    head.position.set(0, 0.7, -0.03)
    this.driver.add(head)

    const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.165, 0.1, 12), creamMat)
    cap.position.set(0, 0.8, -0.03)
    this.driver.add(cap)
    const brim = box(0.24, 0.028, 0.13, creamMat, 0, 0.775, -0.19)
    this.driver.add(brim)

    const armL = rod([-0.22, 0.42, -0.02], [-0.38, 0.14, -0.62], 0.045, shirtMat, 5)
    const armR = rod([0.22, 0.42, -0.02], [0.38, 0.14, -0.62], 0.045, shirtMat, 5)
    this.driver.add(armL, armR)
    for (const x of [-0.39, 0.39]) {
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.052, 6, 6), skinMat)
      hand.position.set(x, 0.12, -0.63)
      this.driver.add(hand)
    }

    this.legs = []
    for (const side of [-1, 1]) {
      const hip = new THREE.Group()
      hip.position.set(side * 0.13, 0.06, 0.04)
      this.driver.add(hip)
      const thigh = box(0.12, 0.36, 0.15, darkMat, 0, -0.18, 0)
      hip.add(thigh)
      const knee = new THREE.Group()
      knee.position.set(0, -0.36, 0)
      hip.add(knee)
      const shin = box(0.1, 0.34, 0.12, skinMat, 0, -0.17, 0)
      knee.add(shin)
      const foot = box(0.12, 0.07, 0.2, darkMat, 0, -0.35, -0.05)
      knee.add(foot)
      this.legs.push({ hip, knee, phase: side > 0 ? 0 : Math.PI })
    }

    // handlebar & bell
    this.model.add(rod([-0.4, 1.02, -1.02], [0.4, 1.02, -1.02], 0.03, darkMat))
    for (const x of [-0.4, 0.4]) {
      this.model.add(rod([x, 1.02, -1.02], [x * 0.5, 0.9, -0.75], 0.026, darkMat))
    }
    this.bell = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 6), goldMat)
    this.bell.position.set(0.26, 1.05, -1.0)
    this.model.add(this.bell)

    // front basket
    const basket = box(0.5, 0.28, 0.34, goldMat, 0, 0.82, -1.12)
    this.model.add(basket)
    const basketInner = box(0.42, 0.2, 0.26, darkMat, 0, 0.85, -1.12)
    this.model.add(basketInner)

    // ---- fake contact shadow --------------------------------------------
    this.shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(2.5, 3.3),
      new THREE.MeshBasicMaterial({
        map: textures.shadow,
        transparent: true,
        depthWrite: false,
        opacity: 0.85,
      }),
    )
    this.shadow.rotation.x = -Math.PI / 2
    this.shadow.position.y = 0.03
    this.shadow.renderOrder = 2
  }

  addToScene() {
    this.scene.add(this.group)
    this.scene.add(this.shadow)
  }

  ringBell() {
    this.bellPulse = 1
  }

  update(dt, { speed = 0, lateral = 0, airborne = false } = {}) {
    this.time += dt
    const t = this.time
    this.wheelSpin += (speed * dt) / 0.34
    for (const wheel of this.wheels) wheel.rotation.x = -this.wheelSpin

    this.bellPulse = Math.max(0, this.bellPulse - dt * 4)
    const pulse = 1 + Math.sin(this.bellPulse * Math.PI) * 0.3
    this.bell.scale.setScalar(pulse)

    const lean = THREE.MathUtils.clamp(-lateral * 0.055, -0.19, 0.19)
    this.tilt.rotation.z += (lean - this.tilt.rotation.z) * Math.min(1, dt * 8)
    this.tilt.rotation.y += (-lateral * 0.05 - this.tilt.rotation.y) * Math.min(1, dt * 6)
    const pitchTarget = airborne ? -0.16 : 0
    this.tilt.rotation.x += (pitchTarget - this.tilt.rotation.x) * Math.min(1, dt * 6)

    const bob = Math.sin(t * 9) * 0.012 + Math.sin(t * 3.1) * 0.008
    this.model.position.y = bob

    this.driver.position.y = 0.9 + Math.sin(t * 9 + 0.6) * 0.018
    this.driver.rotation.z = Math.sin(t * 4.5) * 0.035
    const pedal = t * 7.5
    for (const leg of this.legs) {
      leg.hip.rotation.x = Math.sin(pedal + leg.phase) * 0.5 - 0.35
      leg.knee.rotation.x = Math.max(0, Math.cos(pedal + leg.phase)) * 0.9 + 0.15
    }

    this.flag.rotation.y = Math.PI / 2 + Math.sin(t * 4.4) * 0.2
    this.flag.rotation.z = Math.sin(t * 6.1) * 0.06
  }
}

import * as THREE from '../vendor/three.module.js'

const WRAP = 480
const WRAP_START = 40

function mergeGeometries(geometries) {
  const flat = geometries.map((g) => (g.index ? g.toNonIndexed() : g))
  const merged = new THREE.BufferGeometry()
  for (const name of ['position', 'normal', 'uv']) {
    if (!flat[0].attributes[name]) continue
    const total = flat.reduce((sum, g) => sum + g.attributes[name].count, 0)
    const itemSize = flat[0].attributes[name].itemSize
    const ArrayType = flat[0].attributes[name].array.constructor
    const array = new ArrayType(total * itemSize)
    let offset = 0
    for (const g of flat) {
      array.set(g.attributes[name].array, offset)
      offset += g.attributes[name].array.length
    }
    merged.setAttribute(name, new THREE.BufferAttribute(array, itemSize))
  }
  return merged
}

function box(w, h, d, material, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material)
  mesh.position.set(x, y, z)
  return mesh
}

function mulberry32(seed) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export class World {
  constructor(scene, textures) {
    this.scene = scene
    this.textures = textures
    this.scroll = 0
    this.time = 0
    this.scenery = []
    this.rng = mulberry32(2026)
    this.lampGlows = []
    this.build()

    this.roadTexture = textures.asphalt
    this.sidewalkTexture = textures.sidewalk
  }

  build() {
    const { scene, textures } = this
    const rng = this.rng

    scene.fog = new THREE.FogExp2(0xc27d76, 0.0058)

    // ---------- sky ------------------------------------------------------
    const skyGeo = new THREE.SphereGeometry(340, 32, 20)
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(0x1d1440) },
        mid: { value: new THREE.Color(0x8c3f68) },
        bottom: { value: new THREE.Color(0xffa76a) },
      },
      vertexShader: /* glsl */ `
        varying vec3 vPosition;
        void main() {
          vPosition = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform vec3 top;
        uniform vec3 mid;
        uniform vec3 bottom;
        varying vec3 vPosition;
        void main() {
          float h = normalize(vPosition).y;
          vec3 color = mix(bottom, mid, smoothstep(-0.04, 0.22, h));
          color = mix(color, top, smoothstep(0.16, 0.62, h));
          gl_FragColor = vec4(color, 1.0);
        }
      `,
    })
    this.sky = new THREE.Mesh(skyGeo, skyMat)
    scene.add(this.sky)

    const sun = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: textures.glow,
        color: 0xffd08a,
        transparent: true,
        opacity: 0.95,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    sun.position.set(-62, 26, -250)
    sun.scale.set(80, 80, 1)
    scene.add(sun)

    // ---------- lights ---------------------------------------------------
    scene.add(new THREE.HemisphereLight(0xffd6a8, 0x3a2740, 1.15))
    const key = new THREE.DirectionalLight(0xffb877, 2.1)
    key.position.set(-16, 24, 12)
    scene.add(key)
    const rim = new THREE.DirectionalLight(0x7d8dff, 0.7)
    rim.position.set(12, 10, -18)
    scene.add(rim)

    // ---------- ground ---------------------------------------------------
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(520, 520),
      new THREE.MeshStandardMaterial({ color: 0x342532, roughness: 1 }),
    )
    ground.rotation.x = -Math.PI / 2
    ground.position.y = -0.06
    scene.add(ground)

    textures.asphalt.repeat.set(2, 48)
    const road = new THREE.Mesh(
      new THREE.PlaneGeometry(12, WRAP + 20),
      new THREE.MeshStandardMaterial({ map: textures.asphalt, roughness: 0.82, metalness: 0.08 }),
    )
    road.rotation.x = -Math.PI / 2
    road.position.set(0, 0, -WRAP / 2 + 10)
    scene.add(road)
    this.road = road

    for (const side of [-1, 1]) {
      const sidewalk = new THREE.Mesh(
        new THREE.PlaneGeometry(2, WRAP + 20),
        new THREE.MeshStandardMaterial({ map: textures.sidewalk, roughness: 0.95 }),
      )
      sidewalk.rotation.x = -Math.PI / 2
      sidewalk.position.set(side * 6.7, 0.055, -WRAP / 2 + 10)
      scene.add(sidewalk)

      const curb = box(0.24, 0.16, WRAP + 20, new THREE.MeshStandardMaterial({ color: 0x9d8b78, roughness: 0.9 }), side * 5.68, 0.04, -WRAP / 2 + 10)
      scene.add(curb)

      const wall = new THREE.Mesh(
        new THREE.PlaneGeometry(WRAP, 2.3),
        new THREE.MeshStandardMaterial({ map: textures.wall, roughness: 0.98 }),
      )
      textureWall(textures.wall)
      wall.rotation.y = side * -Math.PI / 2
      wall.position.set(side * 7.82, 1.15, -WRAP / 2 + 10)
      scene.add(wall)

      const wallCap = box(0.2, 0.1, WRAP, new THREE.MeshStandardMaterial({ color: 0x5b4740, roughness: 0.9 }), side * 7.82, 2.32, -WRAP / 2 + 10)
      scene.add(wallCap)
    }

    // lane dashes (periodic, so the whole mesh can scroll)
    const dashMat = new THREE.MeshBasicMaterial({ color: 0xf3dca4 })
    const dashGeo = new THREE.PlaneGeometry(0.16, 2.5)
    dashGeo.rotateX(-Math.PI / 2)
    const perRow = 2
    const rows = Math.ceil((WRAP + 30) / 6)
    const dashes = new THREE.InstancedMesh(dashGeo, dashMat, rows * perRow)
    const matrix = new THREE.Matrix4()
    let index = 0
    for (let i = 0; i < rows; i++) {
      for (let lane = 0; lane < perRow; lane++) {
        matrix.makeTranslation(lane === 0 ? -1.55 : 1.55, 0.02, 32 - i * 6)
        dashes.setMatrixAt(index++, matrix)
      }
    }
    dashes.instanceMatrix.needsUpdate = true
    scene.add(dashes)
    this.dashes = dashes

    // road edges
    for (const side of [-1, 1]) {
      const edge = new THREE.Mesh(
        new THREE.PlaneGeometry(0.12, WRAP + 20),
        new THREE.MeshBasicMaterial({ color: 0xe8c98c, transparent: true, opacity: 0.5 }),
      )
      edge.rotation.x = -Math.PI / 2
      edge.position.set(side * 5.05, 0.021, -WRAP / 2 + 10)
      scene.add(edge)
    }

    // ---------- far skyline ---------------------------------------------
    const silhouetteMat = new THREE.MeshBasicMaterial({ color: 0x4b2b4a })
    for (let i = 0; i < 18; i++) {
      const w = 8 + rng() * 16
      const h = 8 + rng() * 30
      const b = box(w, h, 6, silhouetteMat, -110 + i * 13 + rng() * 4, h / 2, -270 - rng() * 30)
      scene.add(b)
    }

    // ---------- scenery --------------------------------------------------
    const buildingMats = textures.buildings.map((facade) => {
      const front = new THREE.MeshStandardMaterial({ map: facade, roughness: 0.92 })
      const side = new THREE.MeshStandardMaterial({ color: 0x9a7f75, roughness: 0.95 })
      const roof = new THREE.MeshStandardMaterial({ color: 0x554746, roughness: 0.95 })
      return [front, front, roof, roof, side, side]
    })

    for (const side of [-1, 1]) {
      for (let i = 0; i < 9; i++) {
        const z = 24 - i * 52 - rng() * 14
        const w = 9 + rng() * 9
        const d = 6 + rng() * 7
        const h = 6 + rng() * 15
        const group = new THREE.Group()
        group.position.set(side * (10.2 + d / 2 + rng() * 5), 0, z)
        const facadeIndex = Math.floor(rng() * buildingMats.length)
        const body = new THREE.Mesh(new THREE.BoxGeometry(d, h, w), buildingMats[facadeIndex])
        body.position.y = h / 2
        group.add(body)

        const roofMat = new THREE.MeshStandardMaterial({ color: 0x4a3b3d, roughness: 0.95 })
        if (rng() > 0.45) {
          const tank = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 1.6, 8), roofMat)
          tank.position.set(side * -1.2, h + 0.8, rng() * 3 - 1.5)
          group.add(tank)
        }
        if (rng() > 0.5) {
          const rail = box(d, 0.5, w, new THREE.MeshStandardMaterial({ color: 0x6d5a55, roughness: 1, transparent: true, opacity: 0.5 }), 0, h + 0.25, 0)
          group.add(rail)
        }
        scene.add(group)
        this.scenery.push(group)
      }
    }

    // palms
    const trunkMat = new THREE.MeshStandardMaterial({ color: 0x6b4a32, roughness: 1 })
    const leafMat = new THREE.MeshStandardMaterial({ color: 0x2f7d4f, roughness: 0.9, side: THREE.DoubleSide })
    const palmTrunkGeo = new THREE.CylinderGeometry(0.1, 0.22, 4.2, 6)
    const leafBase = new THREE.ConeGeometry(0.3, 2.8, 4, 1)
    leafBase.translate(0, 1.4, 0)
    const palmLeafGeo = (() => {
      const parts = []
      for (let i = 0; i < 7; i++) {
        const clone = leafBase.clone()
        const angle = (i / 7) * Math.PI * 2 + rng() * 0.3
        const droop = 1.05 + rng() * 0.35
        const m = new THREE.Matrix4().compose(
          new THREE.Vector3(0, 4.1, 0),
          new THREE.Quaternion().setFromEuler(new THREE.Euler(0, angle, droop)),
          new THREE.Vector3(1, 0.85 + rng() * 0.25, 0.32),
        )
        clone.applyMatrix4(m)
        parts.push(clone)
      }
      return mergeGeometries(parts)
    })()

    for (const side of [-1, 1]) {
      for (let i = 0; i < 9; i++) {
        const group = new THREE.Group()
        group.position.set(side * (6.85 + rng() * 0.4), 0, 18 - i * 52 - rng() * 22)
        const scale = 0.85 + rng() * 0.4
        group.scale.setScalar(scale)
        const trunk = new THREE.Mesh(palmTrunkGeo, trunkMat)
        trunk.position.y = 2.1
        group.add(trunk)
        const leaves = new THREE.Mesh(palmLeafGeo, leafMat)
        group.add(leaves)
        scene.add(group)
        this.scenery.push(group)
      }
    }

    // banyan clumps
    const banyanTrunkMat = new THREE.MeshStandardMaterial({ color: 0x5a3f2f, roughness: 1 })
    const banyanLeafMat = new THREE.MeshStandardMaterial({ color: 0x2b6440, roughness: 0.95 })
    for (const side of [-1, 1]) {
      for (let i = 0; i < 4; i++) {
        const group = new THREE.Group()
        group.position.set(side * (8.6 + rng() * 2), 0, 0 - i * 118 - rng() * 30)
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.5, 4, 6), banyanTrunkMat)
        trunk.position.y = 2
        group.add(trunk)
        const blobs = []
        for (let b = 0; b < 4; b++) {
          const g = new THREE.SphereGeometry(1.5 + rng() * 1.3, 7, 6)
          g.applyMatrix4(new THREE.Matrix4().makeTranslation((rng() - 0.5) * 3.6, 4.2 + rng() * 2.2, (rng() - 0.5) * 3.6))
          blobs.push(g)
        }
        const canopy = new THREE.Mesh(mergeGeometries(blobs), banyanLeafMat)
        group.add(canopy)
        scene.add(group)
        this.scenery.push(group)
      }
    }

    // lamp posts
    const lampMat = new THREE.MeshStandardMaterial({ color: 0x333037, roughness: 0.7, metalness: 0.4 })
    const lampHeadMat = new THREE.MeshStandardMaterial({ color: 0xffe3a8, emissive: 0xffbe63, emissiveIntensity: 2.4 })
    const postGeo = new THREE.CylinderGeometry(0.07, 0.11, 5.2, 6)
    postGeo.translate(0, 2.6, 0)
    const armGeo = new THREE.BoxGeometry(1.1, 0.08, 0.08)
    armGeo.translate(-0.55, 5.2, 0)
    const headGeo = new THREE.BoxGeometry(0.42, 0.14, 0.26)
    headGeo.translate(-1.02, 5.12, 0)
    const lampGeo = mergeGeometries([postGeo, armGeo, headGeo])
    for (const side of [-1, 1]) {
      for (let i = 0; i < 9; i++) {
        const group = new THREE.Group()
        group.position.set(side * 7.3, 0, 8 - i * 54 - rng() * 8)
        if (side > 0) group.rotation.y = Math.PI
        const post = new THREE.Mesh(lampGeo, lampMat)
        group.add(post)
        const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.17, 8, 6), lampHeadMat)
        bulb.position.set(-1.02, 5.04, 0)
        group.add(bulb)
        const glow = new THREE.Sprite(
          new THREE.SpriteMaterial({
            map: textures.glow,
            color: 0xffb35c,
            transparent: true,
            opacity: 0.62,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
          }),
        )
        glow.scale.set(2.6, 2.6, 1)
        glow.position.set(-1.02, 5.02, 0)
        group.add(glow)
        scene.add(group)
        this.scenery.push(group)
      }
    }

    // tea stalls
    const woodMat = new THREE.MeshStandardMaterial({ color: 0x7a4f30, roughness: 0.95 })
    const tarpMats = [
      new THREE.MeshStandardMaterial({ color: 0x2a7fb8, roughness: 0.85 }),
      new THREE.MeshStandardMaterial({ color: 0xc0392b, roughness: 0.85 }),
      new THREE.MeshStandardMaterial({ color: 0x2a9d8f, roughness: 0.85 }),
    ]
    const bulbMat = new THREE.MeshStandardMaterial({ color: 0xfff2c4, emissive: 0xffcf6b, emissiveIntensity: 2 })
    for (let i = 0; i < 5; i++) {
      const side = i % 2 === 0 ? -1 : 1
      const group = new THREE.Group()
      group.position.set(side * 6.95, 0, -10 - i * 96 - rng() * 24)
      group.rotation.y = side > 0 ? Math.PI : 0
      const counter = box(1.8, 0.9, 0.7, woodMat, 0, 0.45, 0)
      group.add(counter)
      for (const x of [-0.8, 0.8]) {
        for (const z of [-0.5, 0.5]) {
          const post = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.06, 2.3, 5), woodMat)
          post.position.set(x, 1.15, z)
          group.add(post)
        }
      }
      const tarp = box(2.1, 0.06, 1.5, tarpMats[i % tarpMats.length], 0, 2.32, 0)
      tarp.rotation.x = 0.12
      group.add(tarp)
      const kettle = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.16, 0.22, 8), lampMat)
      kettle.position.set(0.35, 1.0, 0)
      group.add(kettle)
      for (const x of [-0.45, 0.05, 0.55]) {
        const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.06, 6, 6), bulbMat)
        bulb.position.set(x, 2.1, 0.1)
        group.add(bulb)
        const halo = new THREE.Sprite(
          new THREE.SpriteMaterial({
            map: textures.glow,
            color: 0xffc46b,
            transparent: true,
            opacity: 0.5,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
          }),
        )
        halo.scale.set(0.8, 0.8, 1)
        halo.position.copy(bulb.position)
        group.add(halo)
      }
      scene.add(group)
      this.scenery.push(group)
    }

    // flags
    for (let i = 0; i < 4; i++) {
      const side = i % 2 === 0 ? -1 : 1
      const group = new THREE.Group()
      group.position.set(side * 6.4, 0, 2 - i * 105)
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.05, 4.4, 5), lampMat)
      pole.position.y = 2.2
      group.add(pole)
      const flag = new THREE.Mesh(
        new THREE.PlaneGeometry(1.05, 0.63),
        new THREE.MeshStandardMaterial({ map: textures.flag, side: THREE.DoubleSide, roughness: 0.85 }),
      )
      flag.position.set(side * -0.55, 3.95, 0)
      group.add(flag)
      const halo = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: textures.glow, color: 0xffe1a1, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false }),
      )
      halo.scale.set(2, 2, 1)
      halo.position.set(side * -0.55, 3.95, 0)
      group.add(halo)
      scene.add(group)
      this.scenery.push(group)
    }

    // puddles
    const puddleMat = new THREE.MeshBasicMaterial({
      map: textures.puddle,
      transparent: true,
      opacity: 0.72,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    for (let i = 0; i < 9; i++) {
      const puddle = new THREE.Mesh(new THREE.PlaneGeometry(2, 1), puddleMat)
      puddle.rotation.x = -Math.PI / 2
      puddle.position.set(-4 + rng() * 8, 0.026, 12 - i * 48 - rng() * 20)
      puddle.scale.set(1 + rng() * 1.4, 1, 1 + rng() * 0.8)
      scene.add(puddle)
      this.scenery.push(puddle)
    }

    // ---------- floating dust -------------------------------------------
    const dustCount = 90
    const dustGeo = new THREE.BufferGeometry()
    const dustPos = new Float32Array(dustCount * 3)
    for (let i = 0; i < dustCount; i++) {
      dustPos[i * 3] = (rng() - 0.5) * 22
      dustPos[i * 3 + 1] = 0.2 + rng() * 5
      dustPos[i * 3 + 2] = 8 - rng() * 52
    }
    dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3))
    this.dust = new THREE.Points(
      dustGeo,
      new THREE.PointsMaterial({
        map: textures.glow,
        color: 0xffd7a1,
        size: 0.16,
        transparent: true,
        opacity: 0.45,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        sizeAttenuation: true,
      }),
    )
    scene.add(this.dust)
  }

  update(dt, speed) {
    this.time += dt
    this.scroll += speed * dt

    const move = speed * dt
    for (const item of this.scenery) {
      item.position.z += move
      if (item.position.z > WRAP_START) item.position.z -= WRAP
    }

    // periodic lane dashes
    this.dashes.position.z = this.scroll % 6
    this.textures.asphalt.offset.y = (this.scroll / 10) % 1
    this.textures.sidewalk.offset.y = (this.scroll / 5.33) % 1

    // dust
    const pos = this.dust.geometry.attributes.position
    for (let i = 0; i < pos.count; i++) {
      let z = pos.getZ(i) + move * 0.65
      let x = pos.getX(i) + Math.sin(this.time * 0.6 + i) * 0.004
      if (z > 10) z -= 60
      if (x > 11) x -= 22
      if (x < -11) x += 22
      pos.setZ(i, z)
      pos.setX(i, x)
    }
    pos.needsUpdate = true
  }
}

function textureWall(texture) {
  texture.repeat.set(60, 1)
}

import * as THREE from '../vendor/three.module.js'

const LANE_X = [-3.1, 0, 3.1]
const RECYCLE_Z = 16

function box(w, h, d, material, x = 0, y = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material)
  mesh.position.set(x, y, z)
  return mesh
}

function wheel(radius, width, material, x, y, z) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, width, 10), material)
  mesh.rotation.z = Math.PI / 2
  mesh.position.set(x, y, z)
  return mesh
}

function glowSprite(texture, color, size, opacity = 0.8) {
  const sprite = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: texture,
      color,
      transparent: true,
      opacity,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }),
  )
  sprite.scale.set(size, size, 1)
  return sprite
}

export class Entities {
  constructor(scene, textures) {
    this.scene = scene
    this.textures = textures
    this.active = []
    this.pools = {}
    this.time = 0

    const tire = new THREE.MeshStandardMaterial({ color: 0x16151a, roughness: 0.9 })
    const gold = new THREE.MeshStandardMaterial({ color: 0xe8b447, roughness: 0.4, metalness: 0.4 })
    const glass = new THREE.MeshStandardMaterial({ color: 0x3c5d6c, roughness: 0.2, metalness: 0.35 })
    const dark = new THREE.MeshStandardMaterial({ color: 0x24222a, roughness: 0.8 })
    this.mats = { tire, gold, glass, dark }

    this.factories = {
      bus: () => this.makeBus(),
      cng: () => this.makeCng(),
      cow: () => this.makeCow(),
      cone: () => this.makeCone(),
      pothole: () => this.makePothole(),
      mango: () => this.makeMango(),
      cha: () => this.makeCha(),
    }
  }

  makeBus() {
    const group = new THREE.Group()
    const side = new THREE.MeshStandardMaterial({ map: this.textures.busSide, roughness: 0.6, metalness: 0.15 })
    const front = new THREE.MeshStandardMaterial({ map: this.textures.busFront, roughness: 0.6, metalness: 0.15 })
    const roof = new THREE.MeshStandardMaterial({ color: 0x0a5d3c, roughness: 0.8 })
    const mats = [side, side, roof, roof, front, roof]
    const body = new THREE.Mesh(new THREE.BoxGeometry(2.35, 2.5, 7), mats)
    body.position.y = 1.55
    group.add(body)

    const bumper = box(2.4, 0.18, 0.2, this.mats.dark, 0, 0.38, 3.52)
    group.add(bumper)
    for (const x of [-1.12, 1.12]) {
      for (const z of [-2.25, 2.25]) {
        group.add(wheel(0.38, 0.26, this.mats.tire, x, 0.38, z))
      }
      const halo = glowSprite(this.textures.glow, 0xffdca3, 1.5, 0.55)
      halo.position.set(x * 0.78, 0.95, 3.55)
      group.add(halo)
    }
    const roofBox = box(1.6, 0.35, 2.4, this.mats.dark, 0, 2.98, 0.4)
    group.add(roofBox)

    group.userData = { kind: 'bus', hw: 1.18, hd: 3.5, jumpable: false, top: 3.1 }
    return group
  }

  makeCng() {
    const group = new THREE.Group()
    const green = new THREE.MeshStandardMaterial({ color: 0x107a4b, roughness: 0.55 })
    const yellow = new THREE.MeshStandardMaterial({ color: 0xf0b429, roughness: 0.55 })
    const body = box(1.5, 1.15, 2.5, green, 0, 0.88, 0)
    group.add(body)
    const roof = box(1.54, 0.16, 2.2, yellow, 0, 1.53, -0.05)
    group.add(roof)
    const windshield = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 0.66), this.mats.glass)
    windshield.position.set(0, 1.22, 1.26)
    group.add(windshield)
    const stripe = box(1.52, 0.1, 2.52, yellow, 0, 0.72, 0)
    group.add(stripe)
    group.add(wheel(0.28, 0.18, this.mats.tire, -0.72, 0.28, 0.82))
    group.add(wheel(0.28, 0.18, this.mats.tire, 0.72, 0.28, 0.82))
    group.add(wheel(0.26, 0.18, this.mats.tire, 0, 0.26, -0.95))
    const sign = box(0.7, 0.2, 0.04, this.mats.dark, 0, 1.44, 1.28)
    group.add(sign)
    for (const x of [-0.42, 0.42]) {
      const halo = glowSprite(this.textures.glow, 0xffe6b0, 0.62, 0.65)
      halo.position.set(x, 0.66, 1.3)
      group.add(halo)
    }
    group.userData = { kind: 'cng', hw: 0.82, hd: 1.35, jumpable: false, top: 1.75 }
    return group
  }

  makeCow() {
    const group = new THREE.Group()
    const white = new THREE.MeshStandardMaterial({ color: 0xe8dcc8, roughness: 0.9 })
    const brown = new THREE.MeshStandardMaterial({ color: 0x8a5432, roughness: 0.9 })
    const horn = new THREE.MeshStandardMaterial({ color: 0xd9c9a2, roughness: 0.7 })
    const body = box(0.85, 0.82, 1.55, white, 0, 0.98, 0)
    group.add(body)
    const head = box(0.44, 0.42, 0.44, white, 0, 1.2, 0.92)
    group.add(head)
    const snout = box(0.34, 0.22, 0.2, brown, 0, 1.08, 1.14)
    group.add(snout)
    for (const x of [-0.16, 0.16]) {
      const ear = box(0.16, 0.08, 0.1, brown, x * 1.9, 1.36, 0.88)
      group.add(ear)
      const h = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.26, 5), horn)
      h.position.set(x, 1.48, 0.92)
      h.rotation.z = x > 0 ? -0.3 : 0.3
      group.add(h)
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.04, 6, 6), this.mats.dark)
      eye.position.set(x, 1.25, 1.14)
      group.add(eye)
    }
    for (const x of [-0.28, 0.28]) {
      for (const z of [-0.52, 0.52]) {
        group.add(box(0.13, 0.6, 0.13, white, x, 0.3, z))
      }
    }
    const tail = box(0.06, 0.6, 0.06, brown, 0, 1.0, -0.82)
    tail.rotation.x = 0.35
    group.add(tail)
    for (let i = 0; i < 3; i++) {
      const patch = new THREE.Mesh(new THREE.SphereGeometry(0.24, 7, 6), brown)
      patch.scale.set(1, 0.7, 1.2)
      patch.position.set(-0.3 + i * 0.3, 1.05 + (i % 2) * 0.22, -0.4 + i * 0.35)
      group.add(patch)
    }
    group.userData = { kind: 'cow', hw: 0.62, hd: 0.95, jumpable: true, top: 1.5 }
    return group
  }

  makeCone() {
    const group = new THREE.Group()
    const orange = new THREE.MeshStandardMaterial({ color: 0xe8571f, roughness: 0.7 })
    const white = new THREE.MeshStandardMaterial({ color: 0xf5eee0, roughness: 0.7 })
    const base = box(0.62, 0.06, 0.62, this.mats.dark, 0, 0.03, 0)
    group.add(base)
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.3, 0.72, 10), orange)
    cone.position.y = 0.42
    group.add(cone)
    const band = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.22, 0.14, 10, 1, true), white)
    band.position.y = 0.46
    group.add(band)
    group.userData = { kind: 'cone', hw: 0.38, hd: 0.38, jumpable: true, top: 0.8 }
    return group
  }

  makePothole() {
    const group = new THREE.Group()
    const rim = new THREE.Mesh(
      new THREE.CircleGeometry(0.72, 14),
      new THREE.MeshStandardMaterial({ color: 0x4a4046, roughness: 1 }),
    )
    rim.rotation.x = -Math.PI / 2
    rim.position.y = 0.012
    group.add(rim)
    const hole = new THREE.Mesh(
      new THREE.CircleGeometry(0.52, 12),
      new THREE.MeshBasicMaterial({ color: 0x0b080e }),
    )
    hole.rotation.x = -Math.PI / 2
    hole.position.y = 0.016
    group.add(hole)
    group.userData = { kind: 'pothole', hw: 0.62, hd: 0.62, jumpable: true, top: 0.1 }
    return group
  }

  makeMango() {
    const group = new THREE.Group()
    const mat = new THREE.MeshStandardMaterial({
      color: 0xffb01f,
      roughness: 0.35,
      metalness: 0.05,
      emissive: 0xff8a00,
      emissiveIntensity: 0.55,
    })
    const fruit = new THREE.Mesh(new THREE.SphereGeometry(0.3, 12, 10), mat)
    fruit.scale.set(1, 1.16, 0.84)
    fruit.rotation.z = 0.35
    group.add(fruit)
    const leaf = new THREE.Mesh(
      new THREE.SphereGeometry(0.16, 7, 5),
      new THREE.MeshStandardMaterial({ color: 0x2f8f4e, roughness: 0.8 }),
    )
    leaf.scale.set(1, 0.24, 0.55)
    leaf.position.set(0.05, 0.36, 0)
    leaf.rotation.z = -0.5
    group.add(leaf)
    const stem = box(0.03, 0.14, 0.03, this.mats.dark, -0.04, 0.31, 0)
    stem.rotation.z = 0.4
    group.add(stem)
    const halo = glowSprite(this.textures.glow, 0xffc356, 1.15, 0.55)
    group.add(halo)
    group.userData = { kind: 'mango', hw: 0.4, hd: 0.4, jumpable: false, top: 1 }
    return group
  }

  makeCha() {
    const group = new THREE.Group()
    const clay = new THREE.MeshStandardMaterial({ color: 0xb35c38, roughness: 0.8 })
    const cup = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.13, 0.28, 12), clay)
    group.add(cup)
    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.19, 0.025, 5, 14), clay)
    rim.rotation.x = Math.PI / 2
    rim.position.y = 0.14
    group.add(rim)
    const tea = new THREE.Mesh(
      new THREE.CircleGeometry(0.16, 12),
      new THREE.MeshStandardMaterial({ color: 0x6b2f14, roughness: 0.3 }),
    )
    tea.rotation.x = -Math.PI / 2
    tea.position.y = 0.145
    group.add(tea)
    const saucer = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.26, 0.03, 14), clay)
    saucer.position.y = -0.16
    group.add(saucer)
    const halo = glowSprite(this.textures.glow, 0xffe6a8, 1.5, 0.6)
    group.add(halo)
    group.userData = { kind: 'cha', hw: 0.4, hd: 0.4, jumpable: false, top: 1 }
    return group
  }

  spawn(kind, lane, z, options = {}) {
    const factory = this.factories[kind]
    if (!factory) return null
    const pool = (this.pools[kind] ||= [])
    const mesh = pool.pop() || factory()
    const laneX = LANE_X[lane] + (options.xOffset || 0)
    mesh.position.set(laneX, 0, z)
    mesh.rotation.y = options.rotation || 0
    mesh.visible = true
    this.scene.add(mesh)
    const entry = {
      mesh,
      kind,
      lane,
      baseY: options.baseY ?? 1.05,
      phase: Math.random() * Math.PI * 2,
      ...mesh.userData,
    }
    if (kind === 'mango' || kind === 'cha') {
      mesh.position.y = entry.baseY
    }
    this.active.push(entry)
    return entry
  }

  release(entry) {
    const index = this.active.indexOf(entry)
    if (index >= 0) this.active.splice(index, 1)
    this.scene.remove(entry.mesh)
    entry.mesh.visible = false
    ;(this.pools[entry.kind] ||= []).push(entry.mesh)
  }

  clear() {
    for (const entry of [...this.active]) this.release(entry)
  }

  update(dt, speed) {
    this.time += dt
    for (let i = this.active.length - 1; i >= 0; i--) {
      const entry = this.active[i]
      entry.mesh.position.z += speed * dt
      if (entry.kind === 'mango' || entry.kind === 'cha') {
        entry.mesh.rotation.y += dt * (entry.kind === 'cha' ? 0.9 : 2.2)
        entry.mesh.position.y = entry.baseY + Math.sin(this.time * 3 + entry.phase) * 0.1
        if (entry.kind === 'cha') entry.mesh.position.y += 0.15
      }
      if (entry.mesh.position.z > RECYCLE_Z) this.release(entry)
    }
  }
}

export { LANE_X }

export class Sound {
  constructor() {
    this.ctx = null
    this.master = null
    this.windGain = null
    this.windFilter = null
    this.muted = false
    this.noiseBuffer = null
  }

  async unlock() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext
      if (!AudioCtx) return
      this.ctx = new AudioCtx()
      this.master = this.ctx.createGain()
      this.master.gain.value = this.muted ? 0 : 0.8
      this.master.connect(this.ctx.destination)
      this.noiseBuffer = this.createNoise()
      this.startWind()
    }
    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume()
      } catch {
        /* ignore */
      }
    }
  }

  createNoise() {
    const duration = 2
    const buffer = this.ctx.createBuffer(1, this.ctx.sampleRate * duration, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1
    return buffer
  }

  startWind() {
    if (!this.ctx) return
    const source = this.ctx.createBufferSource()
    source.buffer = this.noiseBuffer
    source.loop = true
    this.windFilter = this.ctx.createBiquadFilter()
    this.windFilter.type = 'lowpass'
    this.windFilter.frequency.value = 320
    this.windGain = this.ctx.createGain()
    this.windGain.gain.value = 0.012
    source.connect(this.windFilter)
    this.windFilter.connect(this.windGain)
    this.windGain.connect(this.master)
    source.start()
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.8, this.ctx.currentTime, 0.05)
    }
  }

  setIntensity(speed) {
    if (!this.ctx || !this.windGain) return
    const target = 0.01 + Math.min(0.055, speed * 0.0018)
    this.windGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.25)
    this.windFilter.frequency.setTargetAtTime(240 + speed * 14, this.ctx.currentTime, 0.3)
  }

  tone({ freq = 440, to = null, dur = 0.2, type = 'sine', vol = 0.16, delay = 0, attack = 0.01 }) {
    if (!this.ctx || this.muted) return
    const t0 = this.ctx.currentTime + delay
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t0)
    if (to) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur)
    gain.gain.setValueAtTime(0.0001, t0)
    gain.gain.exponentialRampToValueAtTime(vol, t0 + attack)
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start(t0)
    osc.stop(t0 + dur + 0.05)
  }

  noiseBurst({ dur = 0.2, freq = 1200, q = 0.8, vol = 0.12, delay = 0, type = 'bandpass', sweep = null }) {
    if (!this.ctx || this.muted) return
    const t0 = this.ctx.currentTime + delay
    const source = this.ctx.createBufferSource()
    source.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t0)
    if (sweep) filter.frequency.exponentialRampToValueAtTime(sweep, t0 + dur)
    filter.Q.value = q
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(vol, t0)
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
    source.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    source.start(t0)
    source.stop(t0 + dur + 0.02)
  }

  collect(combo = 0) {
    const base = 720 + Math.min(combo, 12) * 38
    this.tone({ freq: base, dur: 0.18, type: 'triangle', vol: 0.12 })
    this.tone({ freq: base * 1.5, dur: 0.22, type: 'sine', vol: 0.09, delay: 0.05 })
  }

  crash() {
    this.noiseBurst({ dur: 0.45, freq: 900, sweep: 120, vol: 0.4, type: 'lowpass' })
    this.tone({ freq: 150, to: 42, dur: 0.5, type: 'sine', vol: 0.35 })
    this.tone({ freq: 85, to: 38, dur: 0.6, type: 'square', vol: 0.08, delay: 0.02 })
  }

  jump() {
    this.tone({ freq: 300, to: 620, dur: 0.16, type: 'sine', vol: 0.1 })
    this.noiseBurst({ dur: 0.12, freq: 700, sweep: 2200, vol: 0.05, type: 'bandpass' })
  }

  lane() {
    this.noiseBurst({ dur: 0.09, freq: 1500, sweep: 700, vol: 0.05, type: 'bandpass' })
  }

  power() {
    const notes = [523, 659, 784, 1046]
    notes.forEach((freq, i) => this.tone({ freq, dur: 0.24, type: 'triangle', vol: 0.1, delay: i * 0.075 }))
  }

  shieldSave() {
    this.tone({ freq: 880, to: 1320, dur: 0.3, type: 'triangle', vol: 0.15 })
    this.noiseBurst({ dur: 0.3, freq: 2400, vol: 0.09, type: 'highpass' })
  }

  click() {
    this.tone({ freq: 520, dur: 0.07, type: 'square', vol: 0.05 })
  }

  start() {
    this.tone({ freq: 660, dur: 0.5, type: 'triangle', vol: 0.14 })
    this.tone({ freq: 990, dur: 0.7, type: 'sine', vol: 0.10, delay: 0.06 })
    this.noiseBurst({ dur: 0.5, freq: 300, sweep: 1800, vol: 0.05, type: 'bandpass' })
  }

  gameOver() {
    const notes = [392, 330, 262, 196]
    notes.forEach((freq, i) => this.tone({ freq, dur: 0.3, type: 'triangle', vol: 0.12, delay: i * 0.16 }))
  }
}

import * as THREE from '../vendor/three.module.js'

const MAX = 180

export class Particles {
  constructor(scene, texture) {
    this.items = []
    this.positions = new Float32Array(MAX * 3)
    this.colors = new Float32Array(MAX * 3)
    this.positions.fill(-999)

    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geometry.setAttribute('color', new THREE.BufferAttribute(this.colors, 3))

    this.points = new THREE.Points(
      geometry,
      new THREE.PointsMaterial({
        map: texture,
        size: 0.3,
        vertexColors: true,
        transparent: true,
        opacity: 0.95,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        sizeAttenuation: true,
      }),
    )
    this.points.frustumCulled = false
    scene.add(this.points)

    for (let i = 0; i < MAX; i++) {
      this.items.push({ active: false, life: 0, maxLife: 1, x: 0, y: -999, z: 0, vx: 0, vy: 0, vz: 0, r: 1, g: 1, b: 1, gravity: 0 })
    }
    this.cursor = 0
  }

  emit(x, y, z, color, count = 12, power = 3, life = 0.6, gravity = 4) {
    const c = new THREE.Color(color)
    for (let n = 0; n < count; n++) {
      const item = this.items[this.cursor]
      this.cursor = (this.cursor + 1) % MAX
      const angle = Math.random() * Math.PI * 2
      const elevation = (Math.random() - 0.2) * 1.6
      const speed = power * (0.35 + Math.random() * 0.9)
      item.active = true
      item.life = life * (0.65 + Math.random() * 0.6)
      item.maxLife = item.life
      item.x = x
      item.y = y
      item.z = z
      item.vx = Math.cos(angle) * speed * Math.cos(elevation)
      item.vy = Math.sin(elevation) * speed + power * 0.4
      item.vz = Math.sin(angle) * speed * Math.cos(elevation)
      item.r = c.r
      item.g = c.g
      item.b = c.b
      item.gravity = gravity
    }
  }

  update(dt, worldSpeed = 0) {
    for (let i = 0; i < MAX; i++) {
      const item = this.items[i]
      if (!item.active) {
        if (this.positions[i * 3 + 1] !== -999) {
          this.positions[i * 3 + 1] = -999
          this.colors[i * 3] = 0
          this.colors[i * 3 + 1] = 0
          this.colors[i * 3 + 2] = 0
        }
        continue
      }
      item.life -= dt
      if (item.life <= 0) {
        item.active = false
        this.positions[i * 3 + 1] = -999
        this.colors[i * 3] = 0
        this.colors[i * 3 + 1] = 0
        this.colors[i * 3 + 2] = 0
        continue
      }
      item.vy -= item.gravity * dt
      item.x += item.vx * dt
      item.y += item.vy * dt
      item.z += (item.vz + worldSpeed * 0.75) * dt
      const fade = Math.min(1, item.life / item.maxLife)
      this.positions[i * 3] = item.x
      this.positions[i * 3 + 1] = item.y
      this.positions[i * 3 + 2] = item.z
      this.colors[i * 3] = item.r * fade
      this.colors[i * 3 + 1] = item.g * fade
      this.colors[i * 3 + 2] = item.b * fade
    }
    this.points.geometry.attributes.position.needsUpdate = true
    this.points.geometry.attributes.color.needsUpdate = true
  }

  clear() {
    for (const item of this.items) item.active = false
    this.positions.fill(-999)
    this.points.geometry.attributes.position.needsUpdate = true
  }
}

import * as THREE from '../vendor/three.module.js'
import { createTextures } from './textures.js'
import { Rickshaw } from './rickshaw.js'
import { World } from './world.js'
import { Entities, LANE_X } from './entities.js'
